import sys
import math
from typing import List, Tuple

def find_minimal_D(N: int, K: int, cities: List[Tuple[int, int, int]]) -> float:
    def distance(p1: Tuple[int, int], p2: Tuple[int, int]) -> float:
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def can_form_happy_county(D: float) -> bool:
        def find(parent: List[int], x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent, parent[x])
            return parent[x]

        def union(parent: List[int], rank: List[int], x: int, y: int) -> None:
            rootX = find(parent, x)
            rootY = find(parent, y)
            if rootX != rootY:
                if rank[rootX] > rank[rootY]:
                    parent[rootY] = rootX
                elif rank[rootX] < rank[rootY]:
                    parent[rootX] = rootY
                else:
                    parent[rootY] = rootX
                    rank[rootX] += 1

        edges = []
        for i in range(N):
            for j in range(i + 1, N):
                dist = distance(cities[i][:2], cities[j][:2])
                if dist <= D:
                    edges.append((dist, i, j))

        edges.sort()

        parent = list(range(N))
        rank = [0] * N

        for dist, u, v in edges:
            union(parent, rank, u, v)

        county_sums = {}
        for i in range(N):
            root = find(parent, i)
            if root not in county_sums:
                county_sums[root] = 0
            county_sums[root] += cities[i][2]

        for county_sum in county_sums.values():
            if any(county_sum % K == 0 for _ in range(K)):
                return True

        return False

    left, right = 0.0, 100000000.0
    while right - left > 1e-6:
        mid = (left + right) / 2
        if can_form_happy_county(mid):
            right = mid
        else:
            left = mid

    return right

